new = r'''// Replace comments with spaces so quoted module names survive but commented-out code doesn't.
const stripJsComments = (src) => {
  let out = '';
  let i = 0;
  let quote = null;
  while (i < src.length) {
    const ch = src[i];
    const next = src[i + 1];
    if (quote) {
      out += ch;
      if (ch === '\\') {
        out += next ?? '';
        i += 2;
        continue;
      }
      if (ch === quote || (ch === '\n' && quote !== '`')) quote = null;
      i += 1;
    } else if (ch === '/' && next === '/') {
      while (i < src.length && src[i] !== '\n') i += 1;
    } else if (ch === '/' && next === '*') {
      const close = src.indexOf('*/', i + 2);
      i = close === -1 ? src.length : close + 2;
      out += ' ';
    } else {
      if (ch === '"' || ch === "'" || ch === '`') quote = ch;
      out += ch;
      i += 1;
    }
  }
  return out;
};

const stripPyComment = (line) => {
  let quote = null;
  for (let i = 0; i < line.length; i += 1) {
    const ch = line[i];
    if (quote) {
      if (ch === '\\') i += 1;
      else if (ch === quote) quote = null;
    } else if (ch === '"' || ch === "'") {
      quote = ch;
    } else if (ch === '#') {
      return line.slice(0, i);
    }
  }
  return line;
};

const JS_IMPORT_PATTERNS = [
  /\bimport\b(?:[^'"`;(]*?\bfrom\s*|\s*)(['"])([^'"\n]+)\1/g,
  /\bexport\b[^'"`;=()]*?\bfrom\s*(['"])([^'"\n]+)\1/g,
  /\brequire\s*\(\s*(['"`])([^'"`\n]+)\1/g,
  /\bimport\s*\(\s*(['"`])([^'"`\n]+)\1/g
];

const extractJsModules = (content) => {
  const src = stripJsComments(content);
  const modules = [];
  for (const pattern of JS_IMPORT_PATTERNS) {
    for (const match of src.matchAll(pattern)) modules.push(match[2].trim());
  }
  return modules;
};

const extractPyModules = (content) => {
  const modules = [];
  const lines = content.replace(/\\\r?\n/g, ' ').split(/\r?\n/);
  for (const raw of lines) {
    for (const stmt of stripPyComment(raw).split(';')) {
      const from = stmt.match(/^\s*(?:[\w ]+:\s*)?from\s+([\w.]+)\s+import\b/);
      if (from) {
        if (!from[1].startsWith('.')) modules.push(from[1]);
        continue;
      }
      const imp = stmt.match(/^\s*(?:[\w ]+:\s*)?import\s+(.+)$/);
      if (imp) {
        for (const part of imp[1].split(',')) {
          const name = part.trim().split(/\s+/)[0];
          if (/^[A-Za-z_][\w.]*$/.test(name)) modules.push(name);
        }
      }
    }
  }
  return modules;
};

const notebookSource = (content) => {
  try {
    const nb = JSON.parse(content);
    return (nb.cells || [])
      .filter((cell) => cell.cell_type === 'code')
      .map((cell) => (Array.isArray(cell.source) ? cell.source.join('') : String(cell.source || '')))
      .join('\n');
  } catch {
    return content;
  }
};

const PY_EXTENSIONS = ['.py', '.ipynb'];
const JS_EXTENSIONS = ['.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs', '.mts', '.cts'];

// Returns [{ name, sep }]; sep is the sub-module separator for the language.
const extractModules = (content, filePath = '') => {
  const ext = String(filePath).toLowerCase().match(/\.[^./\\]+$/)?.[0];
  const isPy = PY_EXTENSIONS.includes(ext);
  const isJs = JS_EXTENSIONS.includes(ext);
  const modules = [];
  if (isPy || !isJs) {
    const src = ext === '.ipynb' ? notebookSource(content) : content;
    for (const name of extractPyModules(src)) modules.push({ name, sep: '.' });
  }
  if (isJs || !isPy) {
    for (const name of extractJsModules(content)) modules.push({ name, sep: '/' });
  }
  return modules;
};

const moduleMatches = (library, { name, sep }) => {
  const mod = name.toLowerCase();
  const lib = library.toLowerCase();
  return mod === lib || mod.startsWith(lib + sep);
};

export const createLibraryDetector = (libraries = DEFAULT_AI_LIBRARIES) => ({
  id: 'libraries',
  analyze({ content, filePath, result }) {
    const modules = extractModules(content, filePath);
    for (const library of libraries) {
      if (modules.some((mod) => moduleMatches(library, mod))) {
        uniqPush(result.aiLibraryMatches, filePath, library);
        result.markAiFile(filePath);
      }
    }
  }
});

